// Layer 0: frame codec.
function encodeAmount(cents) {
  return 'AMT:' + Math.abs(Number(cents));
}

function decodeAmount(frame) {
  return Number(String(frame).replace(/^AMT:/, ''));
}

module.exports = { encodeAmount, decodeAmount };

