// Layer 1: checkout built on Layer 0 codec.
const { encodeAmount, decodeAmount } = require('./codec');

function processRefund(cents) {
  const frame = encodeAmount(-Math.abs(cents));
  return decodeAmount(frame);
}

module.exports = { processRefund };

