// Release gate for promoting Layer 1 to production.
function checkReleaseGate(layer0Passed, layer1PassedCount, layer1TotalCount) {
  return layer0Passed === true && layer1PassedCount === layer1TotalCount;
}

module.exports = { checkReleaseGate };

